12|Bf16KvCausalPlan select_bf16_kv_causal_plan(int heads, int kv_heads_in, int width, int batch,
13|                                            CausalAttentionExecutionEnvelope envelope,
14|                                            int multiprocessor_count) {
15|    if (multiprocessor_count <= 0 || (heads != 24 && heads != 16) || width < 1 || batch < 1 ||
16|        batch > 8 || (batch > 1 && width > 16) || envelope.min_visible_keys == 0 ||
17|        envelope.min_visible_keys > envelope.max_visible_keys ||
18|        envelope.max_visible_keys > kCausalAttentionMaximumVisibleKeys)
19|        throw std::invalid_argument("BF16 attention: invalid plan inputs");
20|    // kv_heads 由调用方传入（27B: 24/4，35B-A3B: 16/2，9B: 16/4）
21|    const int kv_heads = kv_heads_in, group = heads / kv_heads;
22|    const auto ceil_div = [](int a, int b) { return (a + b - 1) / b; };
23|    const int visible   = envelope.max_visible_keys;
24|    if (width > kGroupedPrefillMaxWidth) {
25|        const auto instance =
26|            heads == 16 && width >= 1024 && width % 128 == 0 && visible - width >= 8192
27|                ? Bf16KvInstance::Tiled128
28|                : Bf16KvInstance::Tiled64;
29|        return {instance, {}, heads, width, batch, envelope};
30|    }
31|    const int rows                  = width * group;
32|    const auto instance             = width == 1   ? Bf16KvInstance::GroupedDecode
33|                                      : rows <= 32 ? Bf16KvInstance::Grouped32
34|                                                   : Bf16KvInstance::Grouped64;
35|    const auto description          = bf16_kv_instance_description(instance);
36|    const int tiles                 = ceil_div(rows, description.query_rows);
37|    const int independent_tiles     = batch * kv_heads * tiles;
38|    const bool many_memory_tiles    = description.query_rows == 32 && independent_tiles >= 16;
39|    const bool multiple_query_tiles = tiles > 1;
40|    const std::int64_t sms          = multiprocessor_count;
41|    // Small queries permit up to six CTAs per SM, with a half-SM-count split budget per
42|    // independent query tile. Wider prefill targets two CTAs per SM to limit partial traffic.
43|    const auto long_ctas = width <= 128 / group && (many_memory_tiles || multiple_query_tiles)
44|                               ? std::clamp((sms / 2) * independent_tiles, 2 * sms, 6 * sms)
45|                               : 2 * sms;
46|    Bf16KvPartition partition{1, causal_partition_target(2 * sms, independent_tiles),
47|                              causal_partition_target(long_ctas, independent_tiles),
48|                              description.key_rows};
49|    // The envelope bounds the largest live row. Other batch rows may be shorter.
50|    const int low      = batch == 1 ? static_cast<int>(envelope.min_visible_keys) : 1;
51|    partition.capacity = std::max(
52|        partition.interval_capacity(low, std::min(visible, 32767), partition.normal_target),
53|        partition.interval_capacity(std::max(low, 32768), visible, partition.long_target));
54|    return {instance, partition, heads, width, batch, envelope};
55|}
