111|        const dim3 grid(common::div_up(p.width, Schedule::kQueryRows), Geometry::QHeads);
112|        bf16_kv_tiled_mma_kernel<Geometry, Schedule, Metadata><<<grid, Schedule::kThreads, bytes, stream>>>(p.q, cache.keys, cache.values, metadata,
113|                                                            p.positions, p.scale, p.out, p.width);
114|        CUDA_CHECK(cudaGetLastError());
115|    };
116|    if (!cache.table_rows) {
117|        launch(kv::DirectMetadata{cache.tables});
118|    } else if (cache.valid_columns) {
119|        launch(kv::BatchMetadata<true>{cache.tables, cache.valid_columns, cache.table_rows,
