                const auto src = causal_new_index<G>(head, d, token);
                const auto dst = bf16_kv_cache_index<G>(table[key >> kv::kPageShift], head, d, key & kv::kPageMask);
                common::store_vec(cache_k + dst, ...);
                ...atomic...
