$jl="$Root\_tools\req.jsonl"; Remove-Item -LiteralPath $jl -ErrorAction SilentlyContinue
Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Milliseconds 800
$p=Start-Process -FilePath $Exe -ArgumentList @($Model,'--max-context','4096','--greedy','--host-context-mib','2048','--port','1683','--request-log-jsonl',$jl) -PassThru -WindowStyle Hidden -RedirectStandardOutput "$Root\_tools\ta.out" -RedirectStandardError "$Root\_tools\ta.err"
$sw=[Diagnostics.Stopwatch]::StartNew(); while($sw.Elapsed.TotalSeconds -lt 120){ Start-Sleep -Milliseconds 400; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1683/v1/models' -TimeoutSec 2; break}catch{} }
$plain='{"model":"oxcoder9b-merged","messages":[{"role":"user","content":"Say hi in Chinese"}],"max_tokens":8}'
$tools='{"model":"oxcoder9b-merged","messages":[{"role":"user","content":"Say hi in Chinese"}],"tools":[{"type":"function","function":{"name":"noop","description":"noop","parameters":{"type":"object","properties":{}}}}],"max_tokens":8}'
foreach($b in @($plain,$tools)){ try{ $null=Invoke-RestMethod -Uri 'http://127.0.0.1:1683/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $b -TimeoutSec 60 }catch{} }
Start-Sleep -Seconds 1
if(-not $p.HasExited){ Stop-Process -Id $p.Id -Force }
'---- request log 里的 token 字段 ----'
if(Test-Path -LiteralPath $jl){ $l=Get-Content -LiteralPath $jl; "lines=$($l.Count)"; $l | Select-Object -First 2 | ForEach-Object { if($_.Length -gt 700){ $_.Substring(0,700) } else { $_ } } } else { 'no jsonl' }","description":"用 request-log-jsonl 抓 sampled token ids","workdir":"D:\BaiduNetdiskDownload\Local-AI"}

