                if (allowed_bits > 1) break;
            }
        }
        if (!any_allowed) {
            std::fprintf(stderr, "[grammar] row %zu mask is empty -> unconstrained\n", row);
            return {};
        }
        // [9B 修复] 只剩 1 个候选 = matcher 被冻结（accept 失败后状态不再推进），
