        launch_small(x, weights.first, *weights.second, outputs, stream);
    else
        launch_matrix(x, weights.first, *weights.second, outputs, stream);

diffs.newText:
namespace {
void launch(const Tensor& x, Weights weights, std::span<const Tensor> outputs, MemoryArena*,
            cudaStream_t stream) {
    // [9B 修复] 13..15（partial 尾块）与 16 的整数倍（full 分支）都会让 key/value 两段 NaN：
    // 实测 260 token（partial）正常、272 token（16×17，full）复现 logits NaN。
    // 先把 ≤512 的宽度全部路由到已验证的 4 段独立路径（launch_q4_range / launch_q5_range
    // 对任意 T 都有实现，只是 prefill 会慢一些），确认数值正确后再回头修 launch_matrix。
    if (x.ne[1] <= 512)
        launch_small(x, weights.first, *weights.second, outputs, stream);
    else
        launch_matrix(x, weights.first, *weights.second, outputs, stream);

