  $sw=[Diagnostics.Stopwatch]::StartNew(); while($sw.Elapsed.TotalSeconds -lt 120){ Start-Sleep -Milliseconds 400; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1694/v1/models' -TimeoutSec 2; break}catch{} }
  $c = ('本地推理引擎说明。' * 52)
  $b = @{ model='oxcoder9b-merged'; messages=@(@{role='user';content=$c}); max_tokens=6 } | ConvertTo-Json -Depth 5 -Compress
  try{ $r=Invoke-RestMethod -Uri 'http://127.0.0.1:1694/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $b -TimeoutSec 120; "[$tag] prompt_n=$($r.timings.prompt_n) OK len=$($r.choices[0].message.content.Length)" }catch{ "[$tag] FAIL" }
  if(-not $p.HasExited){ Stop-Process -Id $p.Id -Force }; Start-Sleep -Milliseconds 500
}
