content.arguments:
{"command":"$Root='D:\BaiduNetdiskDownload\Local-AI'; $Exe="$Root\_tools\ninfer-build\apps\ninfer-serve.exe"; $Model="$Root\train\lines\9b-oxcoder\out\oxcoder9b-merged.ninfer"
Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Milliseconds 800
$p=Start-Process -FilePath $Exe -ArgumentList @($Model,'--max-context','4096','--greedy','--host-context-mib','2048','--prefill-chunk','256','--port','1702') -PassThru -WindowStyle Hidden -RedirectStandardOutput "$Root\_tools\tr.out" -RedirectStandardError "$Root\_tools\tr.err"
$sw=[Diagnostics.Stopwatch]::StartNew(); while($sw.Elapsed.TotalSeconds -lt 150){ Start-Sleep -Milliseconds 400; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1702/v1/models' -TimeoutSec 2; break}catch{} }
foreach($n in @(52,80,120)){
  $c = ('本地推理引擎说明。' * $n)
  $b = @{ model='oxcoder9b-merged'; messages=@(@{role='user';content=$c}); max_tokens=6 } | ConvertTo-Json -Depth 5 -Compress
  try{ $r=Invoke-RestMethod -Uri 'http://127.0.0.1:1702/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $b -TimeoutSec 180; "x$n prompt_n=$($r.timings.prompt_n) OK len=$($r.choices[0].message.content.Length)" }catch{ "x$n FAIL" }
}
if(-not $p.HasExited){ Stop-Process -Id $p.Id -Force }","description":"prefill-chunk=256 下测长 prompt 是否恢复","run_in_background":true,"workdir":"D:\BaiduNetdiskDownload\Local-AI"}

