content.arguments:
{"command":"$Root='D:\BaiduNetdiskDownload\Local-AI'; $Exe="$Root\_tools\ninfer-build\apps\ninfer-serve.exe"; $Model="$Root\train\lines\9b-oxcoder\out\oxcoder9b-merged.ninfer"
Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Milliseconds 800
function One([int]$chars){
  $p=Start-Process -FilePath $Exe -ArgumentList @($Model,'--max-context','4096','--greedy','--host-context-mib','2048','--port','1703') -PassThru -WindowStyle Hidden -RedirectStandardOutput "$Root\_tools\ts.out" -RedirectStandardError "$Root\_tools\ts.err"
  $sw=[Diagnostics.Stopwatch]::StartNew(); while($sw.Elapsed.TotalSeconds -lt 90){ Start-Sleep -Milliseconds 400; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1703/v1/models' -TimeoutSec 2; break}catch{} }
  $c = ('本地推理引擎说明。' * [Math]::Max(1,[int]($chars/9)))
  $b = @{ model='oxcoder9b-merged'; messages=@(@{role='user';content=$c}); max_tokens=4 } | ConvertTo-Json -Depth 5 -Compress
  $res=''
  try{ $r=Invoke-RestMethod -Uri 'http://127.0.0.1:1703/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $b -TimeoutSec 90; $res="OK prompt_n=$($r.timings.prompt_n)" }catch{ $res='FAIL' }
  if(-not $p.HasExited){ Stop-Process -Id $p.Id -Force }; Start-Sleep -Milliseconds 400
  "chars=$chars -> $res"
}
foreach($c in @(445,450,455,460)){ One $c }","description":"在 450–470 字符间细化阈值（对应 260–272 token）","workdir":"D:\BaiduNetdiskDownload\Local-AI"}

