$sw=[Diagnostics.Stopwatch]::StartNew(); while($sw.Elapsed.TotalSeconds -lt 120){ Start-Sleep -Milliseconds 400; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1707/v1/models' -TimeoutSec 2; break}catch{} }
# 1) 长 prompt，给足 max_tokens 看内容是否非空
$c = ('本地推理引擎说明。' * 60)
$b = @{ model='oxcoder9b-merged'; messages=@(@{role='user';content=$c}); max_tokens=48 } | ConvertTo-Json -Depth 5 -Compress
try{ $r=Invoke-RestMethod -Uri 'http://127.0.0.1:1707/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $b -TimeoutSec 180; "LONG prompt_n=$($r.timings.prompt_n) finish=$($r.choices[0].finish_reason) len=$($r.choices[0].message.content.Length) >>> $($r.choices[0].message.content.Substring(0,[Math]::Min(60,$r.choices[0].message.content.Length)))" }catch{ 'LONG FAIL' }
# 2) 带 tools（358 token 量级）
$t = @{ model='oxcoder9b-merged'; messages=@(@{role='user';content='Say hi in Chinese'}); tools=@(@{type='function';function=@{name='noop';description='noop';parameters=@{type='object';properties=@{}}}}); max_tokens=32 } | ConvertTo-Json -Depth 8 -Compress
try{ $r2=Invoke-RestMethod -Uri 'http://127.0.0.1:1707/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $t -TimeoutSec 180; "TOOLS prompt_n=$($r2.timings.prompt_n) finish=$($r2.choices[0].finish_reason) len=$($r2.choices[0].message.content.Length)" }catch{ 'TOOLS FAIL' }
if(-not $p.HasExited){ Stop-Process -Id $p.Id -Force }","description":"chunk128 下测长 prompt 内容与 tools 请求","workdir":"D:\BaiduNetdiskDownload\Local-AI"}

