{"command":"$R='D:\BaiduNetdiskDownload\Local-AI'; $M="$R\train\lines\9b-oxcoder\models"; $Out="$R\train\lines\9b-oxcoder\out"
function Sz($p){ if(Test-Path -LiteralPath $p){ $i=Get-Item -LiteralPath $p -Force; if($i.PSIsContainer){ (Get-ChildItem -LiteralPath $p -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum } else { $i.Length } } else { -1 } }
'==== 候选清理项（体积 GB）===='
$cands=@(
 @{p="$Out\.oxcoder-9b-2b-nsfw-GSQ.ninfer.c9r2gmuu.tmp"; why='临时残留 .tmp'},
 @{p="$Out\oxcoder9b-win.ninfer";                        why='未参与验收的产物'},
 @{p="$Out\oxcoder9b-win.ninfer.conversion.json";         why='同上附属'},
 @{p="$M\merged-2b-nsfw-q6-hf";                           why='与 v3 同字节数的重复目录'},
 @{p="$M\merged-2b-nsfw";                                 why='早期中间合并目录'},
 @{p="$M\merged-2b-nsfw-mtp-tuned-v1-reonly";             why='v1 目录（mtp 主文件另存，保留）'}
)
foreach($c in $cands){ $s=Sz $c.p; if($s -ge 0){ '{0,-58} {1,8:N2} GB  {2}' -f $c.p.Replace($R,''), ($s/1GB), $c.why } else { '{0,-58} {1,8}     (不存在)' -f $c.p.Replace($R,''), '--' } }
'==== mtp 目录逐文件 ===='
Get-ChildItem -LiteralPath "$M\mtp" -File | Sort-Object Name | ForEach-Object { '{0,-62} {1,7:N1} MB' -f $_.Name, ($_.Length/1MB) }
'==== 保留项确认 ===='
'{0,-58} {1,8:N2} GB' -f 'models\merged-2b-nsfw-mtp-tuned-v3 (G1 基座)', ((Sz "$M\merged-2b-nsfw-mtp-tuned-v3")/1GB)
'{0,-58} {1,8:N2} GB' -f 'models\OxCoder-9B (原始基座,禁删)', ((Sz "$M\OxCoder-9B")/1GB)
'{0,-58} {1,8:N2} GB' -f 'out\oxcoder9b-merged.ninfer (在跑)', ((Sz "$Out\oxcoder9b-merged.ninfer")/1GB)
'==== 当前 D 余量 ===='; (Get-PSDrive D).Free/1GB","description":"列出待清理项体积与保留项","workdir":"D:\BaiduNetdiskDownload\Local-AI"}

