$before=(Get-PSDrive D).Free/1GB
$del=@(
 "$Out\.oxcoder-9b-2b-nsfw-GSQ.ninfer.c9r2gmuu.tmp",
 "$Out\oxcoder9b-win.ninfer",
 "$Out\oxcoder9b-win.ninfer.conversion.json",
 "$M\merged-2b-nsfw-q6-hf",
 "$M\merged-2b-nsfw-mtp-tuned-v1-reonly",
 "$M\mtp\merged-2b-nsfw-mtp-tuned-v2-mix.safetensors.step0.safetensors",
 "$M\mtp\merged-2b-nsfw-mtp-tuned-v2-mix.safetensors.step300.safetensors",
 "$M\mtp\merged-2b-nsfw-mtp-tuned-v2-mix.safetensors.history.jsonl",
 "$M\mtp\merged-2b-nsfw-mtp-tuned-v3-mix600.safetensors.step0.safetensors",
 "$M\mtp\merged-2b-nsfw-mtp-tuned-v3-mix600.safetensors.step150.safetensors"
)
foreach($p in $del){
  if(Test-Path -LiteralPath $p){
    try{ Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction Stop; "DEL ok : $($p.Replace($R,''))" }
    catch{ "DEL ERR: $($p.Replace($R,'')) -> $($_.Exception.Message)" }
  } else { "SKIP   : $($p.Replace($R,'')) (不存在)" }
}
$after=(Get-PSDrive D).Free/1GB
