Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Seconds 2
Get-ChildItem -LiteralPath "$R\_tools\ninfer-build" -Recurse -Filter 'tokenizer*.obj' -ErrorAction SilentlyContinue | Remove-Item -Force
& 'C:\Program Files (x86)\PowerShell\7\pwsh.exe' -NoLogo -NoProfile -ExecutionPolicy Bypass -File "$R\_tools\build_ninfer.ps1" -Action build 2>&1 | Select-Object -Last 3
$out="$R\train\lines\9b-oxcoder\out\kittyrev-oxcoder9b-nsfw-gate-full-GSQ.ninfer"
$p=Start-Process -FilePath $Exe -ArgumentList @($out,'--max-context','4096','--greedy','--host-context-mib','2048','--prefill-chunk','128','--no-thinking','--port','1734') -PassThru -WindowStyle Hidden -RedirectStandardOutput "$LOGD\g1c.out" -RedirectStandardError "$LOGD\g1c.err"
$sw=[Diagnostics.Stopwatch]::StartNew(); $rd=$false
while($sw.Elapsed.TotalSeconds -lt 180){ Start-Sleep -Milliseconds 500; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1734/v1/models' -TimeoutSec 2; $rd=$true; break}catch{} }
"ready=$rd after $([int]$sw.Elapsed.TotalSeconds)s"
if(-not $rd){ Get-Content -LiteralPath "$LOGD\g1c.err" -Tail 8; exit }
$sets=@('What is 2+2?','Say hello in Chinese.','Explain what a gated delta network is in one sentence.','Write a Python one-liner to reverse a string.','List 3 benefits of unit testing.')
$ok=0;$fail=0
foreach($r in 1..3){ foreach($s in $sets){
  $b=@{model='x';messages=@(@{role='user';content=$s});max_tokens=64}|ConvertTo-Json -Depth 5 -Compress
  try{ $x=Invoke-RestMethod -Uri 'http://127.0.0.1:1734/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $b -TimeoutSec 120
       if($x.choices[0].message.content.Length -gt 0){$ok++}else{$fail++} }catch{$fail++} } }
"==== 5x3 => OK=$ok FAIL=$fail ===="
$b2=@{model='x';messages=@(@{role='user';content='Write a detailed paragraph about local inference engines.'});max_tokens=192}|ConvertTo-Json -Depth 5 -Compress
try{ $r2=Invoke-RestMethod -Uri 'http://127.0.0.1:1734/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $b2 -TimeoutSec 300; "speed: tok=$($r2.usage.completion_tokens) tps=$([math]::Round($r2.timings.predicted_per_second,1))" }catch{ 'speed FAIL' }
if(-not $p.HasExited){ Stop-Process -Id $p.Id -Force }","description":"重编 tokenizer 回退并测新产物 5x3 + 速度","run_in_background":true,"timeoutMs":2400000,"workdir":"D:\BaiduNetdiskDownload\Local-AI"}

