{"command":"$R='D:\BaiduNetdiskDownload\Local-AI'; $NM="$R\train\lines\_shared\tools\ninfer-master"; $PY="$R\train\.venv\Scripts\python.exe"
$out="$R\train\lines\9b-oxcoder\out\kittyrev-oxcoder9b-nsfw-gate-full-GSQ.ninfer"
