Push-Location $NM
& $PY -m tools.convert "--model=.agent-tmp/hf_g1" "--recipe=.agent-tmp/g1/recipe_g1_full_gsq.py" "--components=text,vision,mtp" "--name=kittyrev-oxcoder9b-nsfw-gate-full-GSQ" "--out=$out" *>&1 | Select-Object -Last 4
if(Test-Path $out){ & $PY -m tools.artifact.inspect $out --objects 2>&1 | Select-String -Pattern 'formats:' | ForEach-Object { $_.Line.Trim() } }
Pop-Location
if(Test-Path $out){ $i=Get-Item $out; "产物 {0:N2} GB  {1}" -f ($i.Length/1GB), $i.LastWriteTime.ToString('HH:mm:ss')
  '---- 启动测试 ----'
  $LOGD="$R\_work\ninfer-9b"; $Exe="$R\_tools\ninfer-build\apps\ninfer-serve.exe"
  Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Milliseconds 500
  $p=Start-Process -FilePath $Exe -ArgumentList @($out,'--max-context','4096','--greedy','--host-context-mib','2048','--prefill-chunk','128','--no-thinking','--port','1735') -PassThru -WindowStyle Hidden -RedirectStandardOutput "$LOGD\g1d.out" -RedirectStandardError "$LOGD\g1d.err"
  $sw=[Diagnostics.Stopwatch]::StartNew(); $rd=$false
  while($sw.Elapsed.TotalSeconds -lt 180){ Start-Sleep -Milliseconds 500; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1735/v1/models' -TimeoutSec 2; $rd=$true; break}catch{} }
  "ready=$rd after $([int]$sw.Elapsed.TotalSeconds)s"
  if(-not $rd){ Get-Content -LiteralPath "$LOGD\g1d.err" -Tail 6 } else { Stop-Process -Id $p.Id -Force }
} else { 'NOT CREATED' }","description":"清残留后重转 q8 版并试启动","run_in_background":true,"timeoutMs":3000000,"workdir":"D:\BaiduNetdiskDownload\Local-AI"}

