{"command":"$R='D:\BaiduNetdiskDownload\Local-AI'; $LOGD="$R\_work\ninfer-9b"; $Exe="$R\_tools\ninfer-build\apps\ninfer-serve.exe"
$out="$R\train\lines\9b-oxcoder\out\kittyrev-oxcoder9b-nsfw-gate-full-GSQ.ninfer"
$M='kittyrev-oxcoder9b-nsfw-gate-full-GSQ'
Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Milliseconds 600
$p=Start-Process -FilePath $Exe -ArgumentList @($out,'--max-context','4096','--greedy','--host-context-mib','2048','--prefill-chunk','128','--no-thinking','--port','1746') -PassThru -WindowStyle Hidden -RedirectStandardOutput "$LOGD\g1k.out" -RedirectStandardError "$LOGD\g1k.err"
$sw=[Diagnostics.Stopwatch]::StartNew(); $rd=$false
while($sw.Elapsed.TotalSeconds -lt 200){ Start-Sleep -Milliseconds 500; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1746/v1/models' -TimeoutSec 2; $rd=$true; break}catch{} }
"ready=$rd after $([int]$sw.Elapsed.TotalSeconds)s"
if($rd){
  $sets=@('What is 2+2?','Say hello in Chinese.','Explain what a gated delta network is in one sentence.','Write a Python one-liner to reverse a string.','List 3 benefits of unit testing.')
  $ok=0;$fail=0
  foreach($r in 1..3){ foreach($s in $sets){
    $b=@{model=$M;messages=@(@{role='user';content=$s});max_tokens=64}|ConvertTo-Json -Depth 5 -Compress
    try{ $x=Invoke-RestMethod -Uri 'http://127.0.0.1:1746/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $b -TimeoutSec 120
         if($x.choices[0].message.content.Length -gt 0){$ok++}else{$fail++} }catch{$fail++} } }
  "==== q8-G1 5x3 => OK=$ok FAIL=$fail ===="
  $b2=@{model=$M;messages=@(@{role='user';content='Write a detailed paragraph about local inference engines.'});max_tokens=192}|ConvertTo-Json -Depth 5 -Compress
  try{ $r2=Invoke-RestMethod -Uri 'http://127.0.0.1:1746/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $b2 -TimeoutSec 300; "192tok: tok=$($r2.usage.completion_tokens) tps=$([math]::Round($r2.timings.predicted_per_second,1))" }catch{ "speed FAIL" }
}
Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue","description":"q8-G1 产物 5x3 回归 + 192 token 测速","run_in_background":true,"timeoutMs":1800000,"workdir":"D:\BaiduNetdiskDownload\Local-AI"}

