$A="$R\train\lines\9b-oxcoder\out\kittyrev-oxcoder9b-nsfw-gate-full-GSQ.ninfer"; $LOGD="$R\_work\ninfer-9b"
Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Milliseconds 800
'---- 等价于 run-serve.ps1 的内联启动（验证固化的参数组合）----'
$p=Start-Process -FilePath $Exe -ArgumentList @($A,'--max-context','4096','--greedy','--host-context-mib','2048','--prefill-chunk','128','--no-thinking','--port','1761') -PassThru -WindowStyle Hidden -RedirectStandardOutput "$LOGD\final.out" -RedirectStandardError "$LOGD\final.err"
$sw=[Diagnostics.Stopwatch]::StartNew(); $rd=$false
while($sw.Elapsed.TotalSeconds -lt 200){ Start-Sleep -Milliseconds 500; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1761/v1/models' -TimeoutSec 2; $rd=$true; break}catch{} }
"ready=$rd after $([int]$sw.Elapsed.TotalSeconds)s"
if(-not $rd){ Get-Content -LiteralPath "$LOGD\final.err" -Tail 5 } else {
  $M='kittyrev-oxcoder9b-nsfw-gate-full-GSQ'; $ok=0;$fail=0
  foreach($r in 1..2){ foreach($s in @('What is 2+2?','Say hello in Chinese.','List 3 benefits of unit testing.')){
    $b=@{model=$M;messages=@(@{role='user';content=$s});max_tokens=64}|ConvertTo-Json -Depth 5 -Compress
    try{ $x=Invoke-RestMethod -Uri 'http://127.0.0.1:1761/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $b -TimeoutSec 120; if($x.choices[0].message.content.Length -gt 0){$ok++}else{$fail++} }catch{$fail++} } }
  "==== 固化参数冒烟 2x3 => OK=$ok FAIL=$fail ===="
  Stop-Process -Id $p.Id -Force }","description":"内联验证固化参数组合可用","run_in_background":true,"timeoutMs":900000,"workdir":"D:\BaiduNetdiskDownload\Local-AI"}

