content.arguments:
{"command":"$R='D:\BaiduNetdiskDownload\Local-AI'; $S="$R\train\lines\_shared\tools\ninfer-master\src\ops\linear\projection\bf16"
'---- 1) 在 n2560_k4608.cu 末尾加 n4096_k4608 转发 ----'
$f="$S\shapes\n2560_k4608.cu"
$t=Get-Content -LiteralPath $f -Raw
if($t -notmatch 'select_bf16_n4096_k4608'){
  $t = $t.TrimEnd() + "`r`n`r`n// [9B] vision merger.fc2 (4096, 4608)：K 与 2560_k4608 相同，schedule 实例可直接复用。`r`nBf16Launch select_bf16_n4096_k4608(std::int32_t tokens) {`r`n    return select_bf16_n2560_k4608(tokens);`r`n}`r`n"
  Set-Content -LiteralPath $f -Value $t -NoNewline
}
Select-String -LiteralPath $f -Pattern 'select_bf16_n4096_k4608' | ForEach-Object { "$($_.LineNumber): $($_.Line.Trim())" }
'---- 2) bf16_shapes.h 加声明 ----'
$h="$S\bf16_shapes.h"; $th=Get-Content -LiteralPath $h -Raw
if($th -notmatch 'select_bf16_n4096_k4608'){
  $th = $th.Replace('[[nodiscard]] Bf16Launch select_bf16_n2560_k4608(std::int32_t tokens);', "[[nodiscard]] Bf16Launch select_bf16_n2560_k4608(std::int32_t tokens);`r`n[[nodiscard]] Bf16Launch select_bf16_n4096_k4608(std::int32_t tokens);")
  Set-Content -LiteralPath $h -Value $th -NoNewline
}
Select-String -LiteralPath $h -Pattern 'n4096_k4608' | ForEach-Object { "$($_.LineNumber): $($_.Line.Trim())" }
'---- 3) dispatch 表加项 ----'
$d="$S\bf16_dispatch.cpp"; $td=Get-Content -LiteralPath $d -Raw
if($td -notmatch 'select_bf16_n4096_k4608'){
  $td = $td.Replace('ShapeEntry{2560, 4608, select_bf16_n2560_k4608},', "ShapeEntry{2560, 4608, select_bf16_n2560_k4608},`r`n    ShapeEntry{4096, 4608, select_bf16_n4096_k4608},")
  Set-Content -LiteralPath $d -Value $td -NoNewline
}
Select-String -LiteralPath $d -Pattern '4608' | ForEach-Object { "$($_.LineNumber): $($_.Line.Trim())" }","description":"给 bf16 projection 补 (4096,4608) 形状","workdir":"D:\BaiduNetdiskDownload\Local-AI"}

