// 从内存字节创建 WIC 解码器，返回解码后的 frame 与尺寸
struct DecodedImage {
    ComPtr<IWICBitmapSource> source;
    int                      width  = 0;
    int                      height = 0;
};

DecodedImage open_from_memory(IWICImagingFactory* factory, std::span<const std::uint8_t> bytes,
                              const Policy& policy) {
    if (bytes.empty()) throw Error(ErrorKind::InvalidInput, "empty image input");
    if (bytes.size() > policy.max_bytes)
        throw Error(ErrorKind::BudgetExceeded, "image exceeds max_bytes");

    ComPtr<IWICStream> stream;
    if (FAILED(factory->CreateStream(stream.put())))
        throw Error(ErrorKind::InvalidInput, "WIC: CreateStream failed");
    if (FAILED(stream->InitializeFromMemory(const_cast<BYTE*>(bytes.data()),
                                            static_cast<DWORD>(bytes.size()))))
        throw Error(ErrorKind::InvalidInput, "WIC: InitializeFromMemory failed");

    ComPtr<IWICBitmapDecoder> decoder;
    if (FAILED(factory->CreateDecoderFromStream(stream.get(), nullptr, WICDecodeMetadataCacheOnLoad,
                                                decoder.put())))
        throw Error(ErrorKind::InvalidInput, "WIC: unrecognized image format");

    ComPtr<IWICBitmapFrameDecode> frame;
    if (FAILED(decoder->GetFrame(0, frame.put())))
        throw Error(ErrorKind::InvalidInput, "WIC: cannot decode first frame");

    UINT width = 0, height = 0;

