{"command":"$R='D:\BaiduNetdiskDownload\Local-AI'; $LOGD="$R\_work\ninfer-9b"; $Exe="$R\_tools\ninfer-build\apps\ninfer-serve.exe"
$A="$R\train\lines\9b-oxcoder\out\kittyrev-oxcoder9b-nsfw-gate-full-GSQ.ninfer"
# 起本地静态服务托管 test.jpg
$web=Start-Process -FilePath 'C:\ProgramData\anaconda3\python.exe' -ArgumentList @('-m','http.server','8089','--directory',$LOGD) -PassThru -WindowStyle Hidden -RedirectStandardOutput "$LOGD\web.out" -RedirectStandardError "$LOGD\web.err"
Start-Sleep -Seconds 2
try{ $h=Invoke-WebRequest -Uri 'http://127.0.0.1:8089/test.jpg' -TimeoutSec 5 -UseBasicParsing; "http ok bytes=$($h.RawContentLength)" }catch{ "http FAIL $($_.Exception.Message)" }
Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Milliseconds 500
$p=Start-Process -FilePath $Exe -ArgumentList @($A,'--max-context','4096','--greedy','--host-context-mib','2048','--prefill-chunk','128','--no-thinking','--vision','--port','1774') -PassThru -WindowStyle Hidden -RedirectStandardOutput "$LOGD\vis6.out" -RedirectStandardError "$LOGD\vis6.err"
$sw=[Diagnostics.Stopwatch]::StartNew(); while($sw.Elapsed.TotalSeconds -lt 240){ Start-Sleep -Milliseconds 500; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1774/v1/models' -TimeoutSec 2; break}catch{} }
$body=@{model='kittyrev-oxcoder9b-nsfw-gate-full-GSQ';max_tokens=48;messages=@(@{role='user';content=@(@{type='text';text='这张图里有哪些颜色？一句话中文回答。'},@{type='image_url';image_url=@{url='http://127.0.0.1:8089/test.jpg'}})} )}|ConvertTo-Json -Depth 8 -Compress
try{ $r=Invoke-RestMethod -Uri 'http://127.0.0.1:1774/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $body -TimeoutSec 300; "HTTP-URL VQA OK: [$($r.choices[0].message.content)]" }catch{ $e=$_.Exception.Message; if($_.ErrorDetails -and $_.ErrorDetails.Message){$e=$_.ErrorDetails.Message}; "HTTP-URL FAIL $($e.Substring(0,[Math]::Min(200,$e.Length)))" }
Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue; Stop-Process -Id $web.Id -Force -ErrorAction SilentlyContinue","description":"用本地 http URL 传图，区分 base64 解析与 WIC 解码问题","run_in_background":true,"timeoutMs":900000,"workdir":"D:\BaiduNetdiskDownload\Local-AI"}

