{"command":"$R='D:\BaiduNetdiskDownload\Local-AI'; $S="$R\train\lines\_shared\tools\ninfer-master\src\ops\linear\projection\bf16"
# 1) n8192_k4096.cu 末尾（namespace 内）加转发
$f="$S\shapes\n8192_k4096.cu"; $t=Get-Content -LiteralPath $f -Raw
if($t -notmatch 'select_bf16_n10240_k4096'){
  $t=$t.Replace('} // namespace ninfer::ops::detail', "Bf16Launch select_bf16_n10240_k4096(std::int32_t tokens) {`r`n    return select_bf16_n8192_k4096(tokens);`r`n}`r`n} // namespace ninfer::ops::detail")
  Set-Content -LiteralPath $f -Value $t -NoNewline
}
# 2) 声明
$h="$S\bf16_shapes.h"; $th=Get-Content -LiteralPath $h -Raw
if($th -notmatch 'select_bf16_n10240_k4096'){
  $th=$th.Replace('[[nodiscard]] Bf16Launch select_bf16_n8192_k4096(std::int32_t tokens);',"[[nodiscard]] Bf16Launch select_bf16_n8192_k4096(std::int32_t tokens);`r`n[[nodiscard]] Bf16Launch select_bf16_n10240_k4096(std::int32_t tokens);")
  Set-Content -LiteralPath $h -Value $th -NoNewline
}
# 3) 表项
$d="$S\bf16_dispatch.cpp"; $td=Get-Content -LiteralPath $d -Raw
if($td -notmatch 'select_bf16_n10240_k4096'){
  $td=$td.Replace('ShapeEntry{8192, 4096, select_bf16_n8192_k4096},',"ShapeEntry{8192, 4096, select_bf16_n8192_k4096},`r`n    ShapeEntry{10240, 4096, select_bf16_n10240_k4096},")
  Set-Content -LiteralPath $d -Value $td -NoNewline
}
Select-String -Path "$f","$h","$d" -Pattern 'n10240_k4096' | ForEach-Object { '{0}:{1}: {2}' -f $_.Filename, $_.LineNumber, $_.Line.Trim() }
'---- 重编 ----'
Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Seconds 2
& 'C:\Program Files (x86)\PowerShell\7\pwsh.exe' -NoLogo -NoProfile -ExecutionPolicy Bypass -File "$R\_tools\build_ninfer.ps1" -Action build 2>&1 | Select-Object -Last 3","description":"补 (10240,4096) 形状并重编","run_in_background":true,"timeoutMs":2400000,"workdir":"D:\BaiduNetdiskDownload\Local-AI"}

