content.arguments:
{"command":"$R='D:\BaiduNetdiskDownload\Local-AI'; $LOGD="$R\_work\ninfer-9b"; $Exe="$R\_tools\ninfer-build\apps\ninfer-serve.exe"
$A="$R\train\lines\9b-oxcoder\out\kittyrev-oxcoder9b-nsfw-gate-full-GSQ.ninfer"
Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Milliseconds 600
$p=Start-Process -FilePath $Exe -ArgumentList @($A,'--max-context','4096','--greedy','--host-context-mib','2048','--prefill-chunk','128','--no-thinking','--spec','mtp','--draft-tokens','3','--port','1780') -PassThru -WindowStyle Hidden -RedirectStandardOutput "$LOGD\mtp2.out" -RedirectStandardError "$LOGD\mtp2.err"
$sw=[Diagnostics.Stopwatch]::StartNew(); $rd=$false
while($sw.Elapsed.TotalSeconds -lt 240){ Start-Sleep -Milliseconds 500; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1780/v1/models' -TimeoutSec 2; $rd=$true; break}catch{} }
"mtp ready=$rd after $([int]$sw.Elapsed.TotalSeconds)s"
