$A="$R\train\lines\9b-oxcoder\out\kittyrev-oxcoder9b-nsfw-gate-full-GSQ.ninfer"
Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Milliseconds 600
$p=Start-Process -FilePath $Exe -ArgumentList @($A,'--max-context','4096','--greedy','--host-context-mib','2048','--prefill-chunk','128','--no-thinking','--spec','mtp','--draft-tokens','3','--port','1813') -PassThru -WindowStyle Hidden -RedirectStandardOutput "$LOGD\mtpA.out" -RedirectStandardError "$LOGD\mtpA.err"
$sw=[Diagnostics.Stopwatch]::StartNew(); $rd=$false
while($sw.Elapsed.TotalSeconds -lt 240){ Start-Sleep -Milliseconds 500; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1813/v1/models' -TimeoutSec 2; $rd=$true; break}catch{} }
"mtp ready=$rd after $([int]$sw.Elapsed.TotalSeconds)s"
if(-not $rd){ Get-Content -LiteralPath "$LOGD\mtpA.err" -Tail 4 } else {
  foreach($n in 1..2){
    $b=@{model='kittyrev-oxcoder9b-nsfw-gate-full-GSQ';messages=@(@{role='user';content='Write a detailed paragraph about local inference engines.'});max_tokens=192}|ConvertTo-Json -Depth 5 -Compress
    try{ $r=Invoke-RestMethod -Uri 'http://127.0.0.1:1813/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $b -TimeoutSec 300; "run$n: tps=$([math]::Round($r.timings.predicted_per_second,1)) tok=$($r.usage.completion_tokens)" }catch{ "run$n FAIL" }
  }
  Stop-Process -Id $p.Id -Force }","description":"补 q8(10240,4096) 后测 mtp 投机速度","run_in_background":true,"timeoutMs":900000,"workdir":"D:\BaiduNetdiskDownload\Local-AI"}

