content.arguments:
{"command":"$R='D:\BaiduNetdiskDownload\Local-AI'; $d="$R\train\lines\_shared\tools\ninfer-master\src\ops\linear\projection\q8\q8_dispatch.cpp"
$t=Get-Content -LiteralPath $d -Raw
if($t -notmatch 'q8-miss'){
  $t=$t.Replace('    throw std::invalid_argument("q8 linear: unsupported shape");','    std::fprintf(stderr, "[q8-miss] n=%d k=%d t=%d\n", n, k, t);' + "`r`n" + '    throw std::invalid_argument("q8 linear: unsupported shape");')
  if($t -notmatch '#include <cstdio>'){ $t=$t.Replace('#include <stdexcept>', "#include <cstdio>`r`n#include <stdexcept>") }
  Set-Content -LiteralPath $d -Value $t -NoNewline
}
Select-String -LiteralPath $d -Pattern 'q8-miss' | ForEach-Object { "$($_.LineNumber): $($_.Line.Trim())" }
Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Seconds 2
& 'C:\Program Files (x86)\PowerShell\7\pwsh.exe' -NoLogo -NoProfile -ExecutionPolicy Bypass -File "$R\_tools\build_ninfer.ps1" -Action build 2>&1 | Select-Object -Last 2
$LOGD="$R\_work\ninfer-9b"; $Exe="$R\_tools\ninfer-build\apps\ninfer-serve.exe"
$A="$R\train\lines\9b-oxcoder\out\kittyrev-oxcoder9b-nsfw-gate-full-GSQ.ninfer"
$p=Start-Process -FilePath $Exe -ArgumentList @($A,'--max-context','4096','--greedy','--host-context-mib','2048','--prefill-chunk','128','--no-thinking','--spec','mtp','--draft-tokens','3','--port','1815') -PassThru -WindowStyle Hidden -RedirectStandardOutput "$LOGD\miss.out" -RedirectStandardError "$LOGD\miss.err"
$sw=[Diagnostics.Stopwatch]::StartNew(); while($sw.Elapsed.TotalSeconds -lt 60){ Start-Sleep -Milliseconds 500; if($p.HasExited){break} }
Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue
Get-Content -LiteralPath "$LOGD\miss.err" | Select-String -Pattern 'q8-miss|wv-parts|FATAL' | Select-Object -First 6 | ForEach-Object { $_.Line.Trim() }","description":"打印缺失的 q8 形状 n/k","run_in_background":true,"timeoutMs":2400000,"workdir":"D:\BaiduNetdiskDownload\Local-AI"}

