{"command":"$R='D:\BaiduNetdiskDownload\Local-AI'; $f="$R\train\lines\_shared\tools\ninfer-master\src\ops\linear_attention\gated_delta_net\input_conv\q4_q5\projection_mma.cu"
Copy-Item -LiteralPath $f -Destination "$f.bak-9b" -Force
$t=Get-Content -LiteralPath $f -Raw
$old = '    constexpr std::int32_t kValueRows = 6144;'
$new = @'
    // [9B] value/z 的行数由权重决定（value_z = value + z 合并，各占一半）：
    //   27B: 12288/2 = 6144；9B: 8192/2 = 4096。原来写死 6144 会让 9B 的 verify
    //   在切 value/z 时越界（slice start=4096 len=6144 extent=8192）。
    const std::int32_t kValueRows = static_cast<std::int32_t>(value_z_weight.n / 2);
'@
if($t -match [regex]::Escape($old)){ $t=$t.Replace($old,$new); Set-Content -LiteralPath $f -Value $t -NoNewline; 'patched: kValueRows 运行期化' } else { 'pattern miss' }
Select-String -LiteralPath $f -Pattern 'kValueRows' | Select-Object -First 4 | ForEach-Object { "$($_.LineNumber): $($_.Line.Trim())" }
Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Seconds 2
& 'C:\Program Files (x86)\PowerShell\7\pwsh.exe' -NoLogo -NoProfile -ExecutionPolicy Bypass -File "$R\_tools\build_ninfer.ps1" -Action build 2>&1 | Select-Object -Last 3
$LOGD="$R\_work\ninfer-9b"; $Exe="$R\_tools\ninfer-build\apps\ninfer-serve.exe"
$A="$R\train\lines\9b-oxcoder\out\kittyrev-oxcoder9b-nsfw-gate-full-GSQ.ninfer"
$p=Start-Process -FilePath $Exe -ArgumentList @($A,'--max-context','4096','--greedy','--host-context-mib','2048','--prefill-chunk','128','--no-thinking','--spec','mtp','--draft-tokens','3','--port','1830') -PassThru -WindowStyle Hidden -RedirectStandardOutput "$LOGD\m1.out" -RedirectStandardError "$LOGD\m1.err"
$sw=[Diagnostics.Stopwatch]::StartNew(); $rd=$false
while($sw.Elapsed.TotalSeconds -lt 200){ Start-Sleep -Milliseconds 500; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1830/v1/models' -TimeoutSec 2; $rd=$true; break}catch{} }
"mtp ready=" + $rd
if(-not $rd){ Get-Content -LiteralPath "$LOGD\m1.err" | Select-String -Pattern 'slice-miss|FATAL|miss' | Select-Object -First 4 | ForEach-Object { $_.Line.Trim() } } else {
  $b=@{model='kittyrev-oxcoder9b-nsfw-gate-full-GSQ';messages=@(@{role='user';content='Write a detailed paragraph about local inference engines.'});max_tokens=192}|ConvertTo-Json -Depth 5 -Compress
  foreach($i in 1..3){ try{ $r=Invoke-RestMethod -Uri 'http://127.0.0.1:1830/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $b -TimeoutSec 300; 'run' + $i + ': tps=' + [math]::Round($r.timings.predicted_per_second,1) + ' tok=' + $r.usage.completion_tokens }catch{ 'run' + $i + ' FAIL' } }
  Stop-Process -Id $p.Id -Force }","description":"kValueRows 运行期化后重编并测投机","run_in_background":true,"timeoutMs":2400000,"workdir":"D:\BaiduNetdiskDownload\Local-AI"}

