{"command":"$R='D:\BaiduNetdiskDownload\Local-AI'; $LOGD="$R\_work\ninfer-9b"; $Exe="$R\_tools\ninfer-build\apps\ninfer-serve.exe"
$A="$R\train\lines\9b-oxcoder\out\kittyrev-oxcoder9b-nsfw-gate-full-GSQ.ninfer"
Get-Process ninfer-serve -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.Id -Force }; Start-Sleep -Milliseconds 600
$p=Start-Process -FilePath $Exe -ArgumentList @($A,'--max-context','4096','--greedy','--host-context-mib','2048','--prefill-chunk','128','--no-thinking','--spec','mtp','--draft-tokens','3','--port','1845') -PassThru -WindowStyle Hidden -RedirectStandardOutput "$LOGD\mb.out" -RedirectStandardError "$LOGD\mb.err"
$sw=[Diagnostics.Stopwatch]::StartNew(); $rd=$false
while($sw.Elapsed.TotalSeconds -lt 200){ Start-Sleep -Milliseconds 500; if($p.HasExited){break}; try{$null=Invoke-RestMethod -Uri 'http://127.0.0.1:1845/v1/models' -TimeoutSec 2; $rd=$true; break}catch{} }
"mtp ready=" + $rd
if(-not $rd){ Get-Content -LiteralPath "$LOGD\mb.err" -Tail 3 } else {
  $b=@{model='kittyrev-oxcoder9b-nsfw-gate-full-GSQ';messages=@(@{role='user';content='Write a detailed paragraph about local inference engines.'});max_tokens=192}|ConvertTo-Json -Depth 5 -Compress
  foreach($i in 1..3){ try{ $r=Invoke-RestMethod -Uri 'http://127.0.0.1:1845/v1/chat/completions' -Method Post -ContentType 'application/json' -Body $b -TimeoutSec 300; 'run' + $i + ': tps=' + [math]::Round($r.timings.predicted_per_second,1) + ' tok=' + $r.usage.completion_tokens }catch{ 'run' + $i + ' FAIL' } }
  if(-not $p.HasExited){ Stop-Process -Id $p.Id -Force }
  Get-Content -LiteralPath "$LOGD\mb.err" | Select-String -Pattern 'fold-miss|FATAL|IllegalAddress|unsupported' | Select-Object -First 2 | ForEach-Object { $_.Line.Trim() } }","description":"24 层 fold 编译通过后测 mtp 投机速度","run_in_background":true,"timeoutMs":1200000,"workdir":"D:\BaiduNetdiskDownload\Local-AI"}

