             spec.value_heads, spec.conv_channels);

diffs.newText:
if (spec.layers == 30 && spec.qk_heads == 16 && spec.value_heads == 32 &&
    spec.conv_channels == 8192)
    return FoldGeometryId::Layers30Heads32;
// [9B] fold spec 的 layers 是 GDN 层数（32 层里每 4 层 1 个 full-attn → 24）。
// 必须用独立的 FoldGeometry<24,16,32,8192> 实例，否则 recurrent_fold_kernel 越界读写 state slot。
if (spec.layers == 24 && spec.qk_heads == 16 && spec.value_heads == 32 && spec.conv_channels == 8192)
    return FoldGeometryId::Layers24Heads32;
std::fprintf(stderr, "[fold-miss] layers=%d qk=%d v=%d conv=%d\n", spec.layers, spec.qk_heads,
             spec.value_heads, spec.conv_channels);

